    _class = rf_r1_t10d10_fp32_tree_8(features, features_length); votes[_class] += 1;
    _class = rf_r1_t10d10_fp32_tree_9(features, features_length); votes[_class] += 1;
    
        int32_t most_voted_class = -1;
